#[using="Type"] Lemma ck_user16 : forall h k, wf_L (h_L h) -> wf_chunks' h -> In k (h_chunks h) -> ck_user k mod 16 = 0.
Proof.
  (intros h k WL dd_H; ddestruct dd_H as (WKF & _ & _); intros Hk). pose proof (proj1 (Forall_forall _ _) WKF k Hk) as (WN & WST & WP & WX).
  pose proof (rz_size_mod16 (ck_n k)) as R16. unfold ck_user, ck_rz. pose proof (Z.div_mod (rz_size (ck_n k)) 16 ltac:(lia)) as D16. rewrite R16, Z.add_0_r in D16.
  destruct (ck_prim k).
  - ddestruct WX as (_ & WC & i & Hi & ->). unfold chunk_at. pose proof (region_beg16 (h_L h) (ck_cls k) WL) as RB16.
    pose proof (class_size_mod16 (ck_cls k) ltac:(lia)) as C16. pose proof (Z.div_mod (class_size (ck_cls k)) 16 ltac:(lia)) as DC. rewrite C16, Z.add_0_r in DC.
    pose proof (Z.div_mod (region_beg (h_L h) (ck_cls k)) 16 ltac:(lia)) as DR. rewrite RB16, Z.add_0_r in DR.
    rewrite DR, DC, D16. replace (16 * (region_beg (h_L h) (ck_cls k) / 16) + i * (16 * (class_size (ck_cls k) / 16)) + 16 * (rz_size (ck_n k) / 16))
      with ((region_beg (h_L h) (ck_cls k) / 16 + i * (class_size (ck_cls k) / 16) + rz_size (ck_n k) / 16) * 16) by lia. apply Z_mod_mult.
  - ddestruct WX as (i & _ & MB & _). unfold ck_map_beg in MB. pose proof (Z.div_mod (ck_ab k - 4096) 4096 ltac:(lia)) as DM. rewrite MB, Z.add_0_r in DM.
    rewrite D16. replace (ck_ab k + 16 * (rz_size (ck_n k) / 16)) with (((ck_ab k - 4096) / 4096 * 256 + 256 + rz_size (ck_n k) / 16) * 16) by lia. apply Z_mod_mult.
Qed.
