  #[using="STKLO_OK"] Theorem phaseP_E1 : phaseP_Tc armE1.
  Proof.
    intros Q ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m mo h LB LF A n lo d
      ARMC HOK HM0 XF0 HK0 HJ0 HIN ST LOL SPL SPT SPA MI TP A0 HV CH HFR CONT.
    (* [comment removed for export] *)
    dpose HOK as (EL & AWF & VWF). pose proof (uwc_nonneg _ _ _ _ _ _ _ CH) as D0.
    dpose HM0 as ((_ & HLB) & GM & (GRO & GRW) & GT & GD & GC & GR & GQ & GS & GF & GI & GE).
    dpose AWF as ([WL WLS] & WC & WR & WK & WQ & WS & WD & WB & WBIG & WX & WG).
    set (L := h_L h) in *. set (T := l_T L) in *. set (CTX := l_ctx L) in *. set (TOP := l_top L) in *.
    set (SP := bv_unsigned sp) in *.
    assert (ESP : sp = Z_to_bv 64 SP) by (subst SP; symmetry; apply Z_to_bv_bv_unsigned).
    pose proof WL as WL'. unfold wf_L in WL'.
    ddestruct WL' as (SB16 & B6A & B6B & B6AL & B6LO & B6HI & SEHI & TOPAL & TOP23 & TOPHI & STKLOE & S0TOP & HTOPLO & HTOPHI & HTOPAL & STKLO16 & STKLOC & STKHI47 & STKHIAL
